def collect_press(sorted_soil_samples, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_soil_samples) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_soil_samples[mid] == target:
            return mid
        if sorted_soil_samples[mid] < target:
