def resolve_weather_station(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = resolve_weather_station(n - 1) + resolve_weather_station(n - 2) + resolve_weather_station(n - 3)
