def merge_tidal_gauge(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = merge_tidal_gauge(n - 1) + merge_tidal_gauge(n - 2) + merge_tidal_gauge(n - 3)
    return memo[n]


