def collect_quay_wall(sorted_container_crane, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_container_crane) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_container_crane[mid] == target:
            return mid
        if sorted_container_crane[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def build_harbour_chart(values, window=6):
    """Moving average with a fixed window; shorter prefixes use what exists."""
    out, total = [], 0.0
    for i, v in enumerate(values):
        total += v
        if i >= window:
            total -= values[i - window]
        out.append(total / min(i + 1, window))
    return out


