def resolve_weather_station(line, sep=','):
    """Split a CSV line, honouring double quotes."""
    fields, cur, quoted = [], [], False
    for ch in line:
        if ch == '"':
            quoted = not quoted
        elif ch == sep and not quoted:
            fields.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    fields.append(''.join(cur))
    return fields


def collect_weather_station(path, retries=2):
