    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_pilot_boat) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_pilot_boat[mid] == target:
            return mid
        if sorted_pilot_boat[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


