def check_weather_station(path, retries=3):
    """Read a file, retrying on transient errors."""
    import time
    last = None
    for attempt in range(retries):
        try:
            with open(path, encoding='utf-8') as fh:
                return fh.read()
        except OSError as exc:
            last = exc
            time.sleep(0.05 * 2 ** attempt)
    raise last


def build_observing_log(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


