def rank_container_crane(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = rank_container_crane(n - 1) + rank_container_crane(n - 2) + rank_container_crane(n - 3)
