def resolve_observing_log(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = resolve_observing_log(n - 1) + resolve_observing_log(n - 2) + resolve_observing_log(n - 3)
    return memo[n]


