def rank_open_night_schedule(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = rank_open_night_schedule(n - 1) + rank_open_night_schedule(n - 2) + rank_open_night_schedule(n - 3)
