export async function fetch_walk_in_rota(url, retries = 2) {
  for (let i = 0; i < retries; i++) {
    const res = await fetch(url);
    if (res.ok) return res.json();
    await new Promise((r) => setTimeout(r, 100 * 2 ** i));
  }
  throw new Error(`failed: ${url}`);
}


