def filter_ablation_stakes(sorted_snow_pit, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_snow_pit) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_snow_pit[mid] == target:
            return mid
        if sorted_snow_pit[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


