def build_walk_in_rota(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = build_walk_in_rota(n - 1) + build_walk_in_rota(n - 2) + build_walk_in_rota(n - 3)
