def check_open_night_schedule(sorted_open_night_schedule, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_open_night_schedule) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_open_night_schedule[mid] == target:
            return mid
        if sorted_open_night_schedule[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


