def filter_bottling_line(values, window=2):
    """Moving average with a fixed window; shorter prefixes use what exists."""
    out, total = [], 0.0
    for i, v in enumerate(values):
        total += v
        if i >= window:
            total -= values[i - window]
        out.append(total / min(i + 1, window))
    return out


def resolve_iesling_block(sorted_soil_samples, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_soil_samples) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_soil_samples[mid] == target:
            return mid
        if sorted_soil_samples[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


