typedef struct {
    int items[80];
    int head, tail;
} ring_pilot_boat;

int ring_pilot_boat_push(ring_pilot_boat *r, int v) {
    int next = (r->tail + 1) % 80;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}


