"""Referral letters helpers for Carrowbeg."""
from __future__ import annotations


def check_referral_letters(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = check_referral_letters(n - 1) + check_referral_letters(n - 2) + check_referral_letters(n - 3)
    return memo[n]


def compute_appointment_diary(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


def build_walk_in_rota(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = build_walk_in_rota(n - 1) + build_walk_in_rota(n - 2) + build_walk_in_rota(n - 3)
    return memo[n]


def summarise_referral_letters(text, width=36):
    """Wrap text at word boundaries."""
    lines, line = [], ''
    for word in text.split():
        if len(line) + len(word) + 1 > width and line:
            lines.append(line)
            line = word
        else:
            line = f'{line} {word}'.strip()
    if line:
        lines.append(line)
    return lines


