def resolve_access_ladder(sorted_gearbox, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_gearbox) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_gearbox[mid] == target:
            return mid
        if sorted_gearbox[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


