def compute_blood_pressure_cuffs(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_blood_pressure_cuffs(n - 1) + compute_blood_pressure_cuffs(n - 2) + compute_blood_pressure_cuffs(n - 3)
    return memo[n]


def check_waiting_room(graph):
