from __future__ import annotations


def check_patient_leaflets(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = check_patient_leaflets(n - 1) + check_patient_leaflets(n - 2) + check_patient_leaflets(n - 3)
    return memo[n]


def collect_referral_letters(intervals):
    """Merge overlapping (start, end) pairs."""
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def resolve_blood_pressure_cuffs(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


