def compute_pattern_cards(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_pattern_cards(n - 1) + compute_pattern_cards(n - 2) + compute_pattern_cards(n - 3)
