    int head, tail;
} ring_transformer;

int ring_transformer_push(ring_transformer *r, int v) {
    int next = (r->tail + 1) % 137;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}

