#include <string.h>

void reverse_barrel_room(char *s) {
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

#include <stddef.h>

size_t count_bottling_line(const int *xs, size_t n, int threshold) {
    size_t c = 0;
    for (size_t i = 0; i < n; i++)
        if (xs[i] > threshold)
            c++;
    return c;
}


