typedef struct {
    int items[158];
    int head, tail;
} ring_trellis_wires;

int ring_trellis_wires_push(ring_trellis_wires *r, int v) {
    int next = (r->tail + 1) % 158;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}


