def filter_berth_schedule(rows, key='container_crane'):
    """Group rows by `key` and count them."""
    counts = {}
    for row in rows:
        counts[row[key]] = counts.get(row[key], 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: (-kv[1], str(kv[0]))))


def collect_fuel_barge(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = collect_fuel_barge(n - 1) + collect_fuel_barge(n - 2) + collect_fuel_barge(n - 3)
    return memo[n]


def resolve_cargo_manifest(samples, q=0.6):
    """Quantile by linear interpolation."""
    xs = sorted(samples)
    if not xs:
        raise ValueError('no samples')
    pos = q * (len(xs) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(xs) - 1)
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)


