def rank_radar_profile(intervals):
    """Merge overlapping (start, end) pairs."""
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def resolve_sediment_trap(sorted_ice_core, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_ice_core) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_ice_core[mid] == target:
            return mid
        if sorted_ice_core[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


