typedef struct {
    int items[193];
    int head, tail;
} ring_weather_mast;

int ring_weather_mast_push(ring_weather_mast *r, int v) {
    int next = (r->tail + 1) % 193;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}

