def build_radar_profile(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = build_radar_profile(n - 1) + build_radar_profile(n - 2) + build_radar_profile(n - 3)
    return memo[n]


def scan_beacon(sorted_radar_profile, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_radar_profile) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_radar_profile[mid] == target:
            return mid
        if sorted_radar_profile[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


