def filter_terminus_marker(sorted_sediment_trap, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_sediment_trap) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_sediment_trap[mid] == target:
